import { collection, getDocs } from "firebase/firestore"; // Firebase функции за извличане на данни
import { db } from "../../config/firebaseConfig"; // Импортиране на конфигурацията за Firestore

export async function getMessages() {
    try {
        // Получаваме референция към колекцията 'messages' в Firestore
        const messagesRef = collection(db, "messages");

        // Извличаме всички документи от колекцията 'messages'
        const querySnapshot = await getDocs(messagesRef);

        // Преобразуваме документите в масив
        const messages = querySnapshot.docs.map(doc => ({
            id: doc.id,  // Взимаме ID на документа
            ...doc.data() // Взимаме данните на документа
        }));

        return { status: 200, messages }; // Връщаме успешен отговор със съобщенията
    } catch (error) {
        console.error("Error fetching messages:", error);
        return { status: 500, message: "Failed to fetch messages." }; // В случай на грешка
    }
}
